def pancake_sort(arr):
    if len(arr) == 1:
        return arr
    pivot = arr[len(arr) // 2]
    left = [x for x in arr if x < pivot]
    middle = [x for x in arr if x == pivot]
    right = [x for x in arr if x > pivot]
    return pancake_sort(left) + middle + pancake_sort(right)

