def max_path_sum(triangle, n, m):
    # Base case
    if n == 1:
        return triangle[0][0]
    if n == 2:
        return max(triangle[0][0], triangle[1][0])
    # Recursive case
    return max(triangle[n-1][0] + max_path_sum(triangle, n-1, m), 
               triangle[n-1][m-1] + max_path_sum(triangle, n-1, m-1))

def longest_subseq_with_diff_one(arr, diff):
    n = len(arr)
    dp = [[0 for _ in range(diff + 1)] for _ in range(n)]
    for i in range(n):
        dp[i][0] = 1
    for i in range(1, diff + 1):
        dp[0][i] = 0
    for i in range(1, n):
        for j in range(1, diff + 1):
            if arr[i - 1] == arr[i] + 1:
                dp[i][j] = dp[i - 1][j - 1] + 1
            else:
                dp[i][j] = max(dp[i - 1][j], dp[i - 1][j - 1])
    return dp[n - 1][diff]

