    pos = []
    neg = []
    for i in range(n):
        if arr[i] >= 0:
            pos.append(arr[i])
        else:
            neg.append(arr[i])
    # Sort the positive and negative elements
    pos.sort()
    neg.sort()
    # Re-arrange the elements
    for i in range(n):
