def is_subset_sum(arr, sum, target):
    # Create a dictionary to store the frequency of each element
    freq = {}
    for num in arr:
        if num in freq:
            freq[num] += 1
        else:
            freq[num] = 1

    # Create a list to store the possible combinations
    combinations = []
    # Iterate through the frequency dictionary
    for num in freq:
        # Check if the sum of the current element and the remaining elements is equal to the target
        if num + sum - target in freq:
            # Add the combination to the list
            combinations.append((num, num + sum - target))

    # Return True if there is a combination with the given sum
    return len(combinations) > 0

